import { isBrowser } from "./platform.js";
// Create a promise that resolves to the logger
const loggerPromise = (async () => {
    if (isBrowser) {
        // Browser implementation (no-op)
        return {
            error: console.error,
            warn: console.warn,
            info: console.log,
            debug: console.log,
            checklist: console.log,
        };
    }
    else {
        // Node.js implementation (using Winston)
        const winston = await import("winston");
        const { createLogger, format, transports } = winston;
        const winstonLogger = createLogger({
            level: "info",
            levels: {
                error: 0,
                warn: 1,
                info: 2,
                debug: 3,
                checklist: 4,
            },
            format: format.combine(format.timestamp(), 
            // deno-lint-ignore no-explicit-any
            format.printf((info) => {
                if (info.level === "checklist") {
                    return info.message;
                }
                return `${info.timestamp} [${info.level.toUpperCase()}]: ${info.message} ${Object.keys(info).length > 3
                    ? JSON.stringify(Object.assign({}, info, {
                        timestamp: undefined,
                        level: undefined,
                        message: undefined,
                    }))
                    : ""}`;
            })),
            transports: [
                new transports.Console({
                    level: "checklist",
                }),
            ],
        });
        // Create a logger object that matches our Logger interface
        const logger = {
            error: (message, ...meta) => winstonLogger.error(message, ...meta),
            warn: (message, ...meta) => winstonLogger.warn(message, ...meta),
            info: (message, ...meta) => winstonLogger.info(message, ...meta),
            debug: (message, ...meta) => winstonLogger.debug(message, ...meta),
            checklist: (message) => winstonLogger.log("checklist", message),
            add: (transport) => winstonLogger.add(transport),
        };
        return logger;
    }
})();
// Export the logger promise for advanced usage
export { loggerPromise as logger };
// Async wrapper for logging functions
const createAsyncLogger = (level) => async (message, ...meta) => {
    const logger = await loggerPromise;
    if (logger[level]) {
        logger[level](message, ...meta);
    }
};
// Exports
export const error = createAsyncLogger("error");
export const warn = createAsyncLogger("warn");
export const info = createAsyncLogger("info");
export const debug = createAsyncLogger("debug");
export const checklist = createAsyncLogger("checklist");
export const LogLevels = {
    ERROR: "error",
    WARN: "warn",
    INFO: "info",
    DEBUG: "debug",
    CHECKLIST: "checklist",
};
// Cursor manipulation methods (these will only work in Node.js environment)
export const cursor = {
    up: (n) => isBrowser ? undefined : console.log(`\x1b[${n}A`),
    clear: () => isBrowser ? undefined : console.log("\x1b[0J"),
    move: (x, y) => isBrowser ? undefined : console.log(`\x1b[${y};${x}H`),
};
// Setup logging function (no-op in browser)
export const setupLogging = async (level) => {
    if (!isBrowser) {
        const loggerInstance = await loggerPromise;
        // Assuming the Winston logger is accessible here
        // deno-lint-ignore no-explicit-any
        loggerInstance.level = level;
    }
};
